function N({registerIndicator:h,nulls:m}){h({id:"oa-willr",name:"Williams %R (WILLR)",category:"Oscillators",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:14,min:1,max:100,step:1,tooltip:"Lookback period for highest high and lowest low calculation"}],plots:[{key:"willr",type:"line",title:"Williams %R",style:{color:"#ffeb3b",lineWidth:2}}],calc(i,u){const f=Math.max(1,Math.min(100,Math.floor(Number(u.period)||14))),n=new Array(i.length).fill(NaN);for(let e=0;e<i.length;e++){const p=Math.max(0,e-f+1);let t=NaN,l=NaN;for(let o=p;o<=e;o++){const a=i[o].high,r=i[o].low;Number.isFinite(a)&&(!Number.isFinite(t)||a>t)&&(t=a),Number.isFinite(r)&&(!Number.isFinite(l)||r<l)&&(l=r)}const s=t-l;if(!(s>0)){n[e]=-50;continue}const c=i[e].close;Number.isFinite(c)&&(n[e]=-100*(t-c)/s)}return{willr:m(n)}}})}export{N as default};
